use vstd::prelude::*;

verus! {

/// Returns a fresh vector with the same elements as `a` in the same order.
/// Does not modify `a`.
fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    ensures
        // same length
        result.len() == a.len(),
        // pointwise equality
        forall|i: int| 0 <= i && i < a.len() ==> result[i] == a[i],
        // convenient extensional view
        result@ == a@,
{
    let mut result: Vec<T> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            i <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j && j < i ==> result[j] == a[j],
            result@ == a@.subrange(0, i as int),
    {
        result.push(a[i]);
        i += 1;
    }

    result
}

}